  factory RenewRequest.fromJson(Map<String, dynamic> j) => RenewRequest(channel: j['channel'] as String, uid: j['uid'] as String);

  final String channel;
  final String uid;

  Map<String, dynamic> toJson() => {'channel': channel, 'uid': uid};
}

class StartRequest {
  const StartRequest({required this.channel, required this.uid, this.captions});

  factory StartRequest.fromJson(Map<String, dynamic> j) =>
      StartRequest(channel: j['channel'] as String, uid: j['uid'] as String, captions: j['captions'] == null ? null : VoiceCaptions.fromJson(j['captions']));

  final String channel;
  final String uid;
  final VoiceCaptions? captions;

  Map<String, dynamic> toJson() => {'channel': channel, 'uid': uid, if (captions != null) 'captions': captions!.wire};
}

class VerifyRequest {
  const VerifyRequest({required this.code});

  factory VerifyRequest.fromJson(Map<String, dynamic> j) => VerifyRequest(code: j['code'] as String);

  final String code;

  Map<String, dynamic> toJson() => {'code': code};
}

class ConnectorsChannelRequest {
  const ConnectorsChannelRequest({required this.channel});

  factory ConnectorsChannelRequest.fromJson(Map<String, dynamic> j) => ConnectorsChannelRequest(channel: j['channel'] as String);

  final String channel;

  Map<String, dynamic> toJson() => {'channel': channel};
}

class SetOpenRequest {
  const SetOpenRequest({required this.open});

  factory SetOpenRequest.fromJson(Map<String, dynamic> j) => SetOpenRequest(open: j['open'] as bool);

  final bool open;

  Map<String, dynamic> toJson() => {'open': open};
}

class AnswerPairingRequest {
  const AnswerPairingRequest({required this.allow});

  factory AnswerPairingRequest.fromJson(Map<String, dynamic> j) => AnswerPairingRequest(allow: j['allow'] as bool);

  final bool allow;

  Map<String, dynamic> toJson() => {'allow': allow};
}

